<template>
  <div class="forest-shell">
    <aside>
      <div class="logo"><el-icon><MostlyCloudy /></el-icon><div><b>福州国家森林公园</b><span>古树防火巡护平台</span></div></div>
      <el-menu :default-active="active" class="side-menu" @select="selectMenu">
        <el-menu-item index="overview"><el-icon><DataBoard /></el-icon><span>防火态势</span></el-menu-item>
        <el-menu-item index="ancient"><el-icon><Sunny /></el-icon><span>古树监测</span></el-menu-item>
        <el-menu-item index="history"><el-icon><TrendCharts /></el-icon><span>历史趋势</span></el-menu-item>
        <el-menu-item index="incidents"><el-icon><Warning /></el-icon><span>火情事件</span><span v-if="pendingCount" class="menu-count" :aria-label="`未处理火情 ${pendingCount} 条`"><b>{{ pendingCount > 99 ? '99+' : pendingCount }}</b></span></el-menu-item>
        <el-menu-item index="drone"><el-icon><Position /></el-icon><span>无人机巡护</span></el-menu-item>
        <el-menu-item index="broadcast"><el-icon><Bell /></el-icon><span>广播与疏散</span></el-menu-item>
        <el-menu-item index="equipment"><el-icon><Monitor /></el-icon><span>设备运行保障</span><span v-if="equipmentFaultCount" class="menu-count" :aria-label="`待处理设备异常 ${equipmentFaultCount} 条`"><b>{{ equipmentFaultCount > 99 ? '99+' : equipmentFaultCount }}</b></span></el-menu-item>
      </el-menu>
      <div class="account"><el-avatar>{{ userName.charAt(0) }}</el-avatar><div><b>{{ userName }}</b><span>护林员</span></div><el-button text circle @click="logout"><el-icon><SwitchButton /></el-icon></el-button></div>
    </aside>

    <main>
      <header><div><div class="eyebrow">{{ pageMeta.eyebrow }}</div><h1>{{ pageMeta.title }}</h1><p>{{ pageMeta.subtitle }}</p></div><div class="header-actions"><div class="weather" :title="`${weather.source || '天气数据加载中'}${weather.observedAt ? ' · '+weather.observedAt : ''}`"><el-icon><Sunny /></el-icon><div><b>{{ weatherSummary }}</b><span>{{ parkInfo.fireRisk || '—' }}森林火险 · {{ weather.stale ? '降级数据' : '实时天气' }}</span></div></div><el-button plain @click="router.push('/mobile')"><el-icon><Iphone /></el-icon> 移动端</el-button></div></header>

      <template v-if="active==='overview'">
        <el-alert v-if="primaryAlert" :title="`${primaryAlert.zone}：${primaryAlert.reason}`" type="error" :closable="false" show-icon class="top-alert"><el-button size="small" type="danger" @click="reviewCamera(primaryAlert)">摄像头复查</el-button></el-alert>
        <section class="stats">
          <article><div class="stat-icon green"><el-icon><Sunny /></el-icon></div><div><span>重点保护古树</span><b>{{ parkInfo.ancientTrees }}<small>株</small></b><em>2个古树保护区</em></div></article>
          <article><div class="stat-icon orange"><el-icon><Warning /></el-icon></div><div><span>当前火险等级</span><b>{{ parkInfo.fireRisk || '—' }}</b><em>{{ riskAnalysis.algorithm || '多源模型' }} · {{ riskAnalysis.score ?? '—' }}分</em></div></article>
          <article><div class="stat-icon red"><el-icon><Bell /></el-icon></div><div><span>待核查火情</span><b>{{ pendingCount }}<small>起</small></b><em>需摄像头或无人机复查</em></div></article>
          <article><div class="stat-icon blue"><el-icon><Position /></el-icon></div><div><span>可用无人机</span><b>{{ availableDrones }}<small>/{{ drones.length }}</small></b><em>任务状态由数据库实时汇总</em></div></article>
        </section>
        <section class="overview-grid">
          <el-card class="map-panel" shadow="never"><template #header><div class="card-head"><div><b>景区防火态势图</b><span>步道、河流与巡护力量实时态势</span></div><div class="map-head-actions"><div class="legend"><i class="normal"></i>正常<i class="warn"></i>警情关注<i class="danger"></i>疏散警戒</div><el-button size="small" @click="openZoneManager">分区管理</el-button></div></div></template>
            <div class="forest-map">
              <ForestMap ref="forestMapRef" :zones="mapZones" :markers="mapMarkers" :center="mapCenter" :zoom="mapZoom" interactive @select-zone="selectMapZone" @draw-complete="onDrawComplete" @view-change="onViewChange" />
              <svg v-if="false" class="park-base" viewBox="0 0 1000 620" preserveAspectRatio="none" aria-label="福州国家森林公园防火分区图">
                <defs><linearGradient id="mapBg" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#ccdcbe"/><stop offset=".5" stop-color="#b3c8a4"/><stop offset="1" stop-color="#9bb691"/></linearGradient><radialGradient id="hillN" cx="30%" cy="22%" r="62%"><stop stop-color="#9fc093" stop-opacity=".55"/><stop offset="1" stop-color="#9fc093" stop-opacity="0"/></radialGradient><radialGradient id="hillE" cx="78%" cy="28%" r="55%"><stop stop-color="#89ab86" stop-opacity=".5"/><stop offset="1" stop-color="#89ab86" stop-opacity="0"/></radialGradient><filter id="roadShadow"><feDropShadow dx="0" dy="2" stdDeviation="2" flood-opacity=".18"/></filter><pattern id="trees" width="34" height="34" patternUnits="userSpaceOnUse"><circle cx="7" cy="9" r="2.7" fill="#2f5c3c" opacity=".16"/><circle cx="26" cy="24" r="2" fill="#31613f" opacity=".13"/><circle cx="18" cy="5" r="1.4" fill="#3c6b46" opacity=".12"/></pattern></defs>
                <rect width="1000" height="620" fill="url(#mapBg)"/><rect width="1000" height="620" fill="url(#trees)"/><rect width="1000" height="620" fill="url(#hillN)"/><rect width="1000" height="620" fill="url(#hillE)"/>
                <path class="contour-line" d="M-30 150 C120 16 300 40 430 150 S660 268 786 120 C866 24 962 76 1028 172"/><path class="contour-line" d="M-40 224 C130 87 303 116 415 212 S663 338 813 188 C895 106 984 142 1035 228"/><path class="contour-line" d="M-25 500 C130 385 270 400 386 502 S670 655 836 514 C915 448 975 460 1020 502"/><path class="contour-line" d="M40 60 C180 -10 330 12 420 88 S640 210 800 70 C880 -10 960 30 1010 100"/>
                <path class="forest-mass deep" d="M0 0 H440 C380 70 400 130 340 200 C275 275 130 250 40 300 C-20 330 -30 240 0 180 Z"/><path class="forest-mass" d="M500 0 H1000 V250 C895 285 815 232 745 165 C675 98 592 100 530 30 Z"/><path class="forest-mass soft" d="M0 360 C120 300 230 335 330 415 C430 500 540 500 610 620 H0 Z"/><path class="forest-mass soft" d="M720 300 C815 262 930 300 1000 360 V620 H590 C660 530 650 410 720 300 Z"/>
                <path class="water-bank" d="M860 -30 C800 90 905 160 830 240 C765 315 880 380 800 460 C735 525 790 585 760 660"/><path class="waterway" d="M860 -30 C800 90 905 160 830 240 C765 315 880 380 800 460 C735 525 790 585 760 660"/>
                <g class="zone-shape high" @click="selectedZone=zones[0]"><path d="M42 62 C90 28 152 20 208 40 C266 60 300 38 332 70 C362 102 352 152 322 188 C292 224 322 262 286 296 C250 330 182 320 130 302 C82 284 62 312 46 282 C30 252 56 222 48 192 C40 162 18 132 30 96 C38 70 18 66 42 62 Z"/><text x="150" y="152">千年银杏古树区</text><text class="zone-sub" x="150" y="178">古树核心区 · 游客禁入</text></g>
                <g class="zone-shape mid" @click="selectedZone=zones[1]"><path d="M356 44 C420 16 502 22 546 52 C592 82 612 132 590 172 C568 212 586 252 546 276 C506 300 430 292 396 262 C362 232 340 252 330 216 C320 180 346 146 340 102 C336 72 328 56 356 44 Z"/><text x="455" y="160">香樟古树群</text><text class="zone-sub" x="455" y="186">古树保护区 · 仅开放观景边界</text></g>
                <g class="zone-shape high" @click="selectedZone=zones[4]"><path d="M700 60 C760 30 860 24 912 60 C962 96 1012 132 996 192 C980 252 1002 292 960 332 C920 372 828 352 790 302 C752 252 742 202 720 162 C700 122 690 92 700 60 Z"/><text x="836" y="190">南坡生态林</text><text class="zone-sub" x="836" y="216">重点巡护林区</text></g>
                <path class="visitor-boundary" d="M298 400 C360 368 462 372 532 396 C612 420 702 402 782 422 C862 442 882 482 852 532 C822 582 740 596 660 586 C572 576 502 602 422 586 C352 572 292 546 288 492 C284 442 286 416 298 400 Z"/><text class="visitor-boundary-label" x="600" y="560">游客开放活动范围</text>
                <g class="zone-shape low" @click="selectedZone=zones[2]"><path d="M360 452 C400 430 460 430 492 448 C522 464 512 500 482 512 C448 526 388 520 364 498 C346 482 344 464 360 452 Z"/><text x="425" y="488">游客服务中心</text></g>
                <g class="zone-shape mid" @click="selectedZone=zones[3]"><path d="M688 448 C724 430 774 434 800 456 C824 476 814 510 784 520 C750 532 700 526 678 506 C662 490 664 460 688 448 Z"/><text x="738" y="488">无火露营区</text></g>
                <g filter="url(#roadShadow)"><path class="road-outline" d="M470 625 C466 594 496 578 488 550 C480 522 444 530 437 503 C430 476 468 470 461 444 C454 418 420 428 418 402 C416 376 450 372 445 348 C440 324 408 330 413 305 C418 280 450 278 439 254 C428 230 394 240 399 214 C404 188 372 184 362 166"/><path class="road-main" d="M470 625 C466 594 496 578 488 550 C480 522 444 530 437 503 C430 476 468 470 461 444 C454 418 420 428 418 402 C416 376 450 372 445 348 C440 324 408 330 413 305 C418 280 450 278 439 254 C428 230 394 240 399 214 C404 188 372 184 362 166"/><path class="road-minor" d="M439 254 C480 238 524 244 546 224 M413 305 C462 314 502 300 522 272 M362 166 C330 150 302 158 288 142 M461 444 C502 452 534 468 556 490 M399 214 C404 234 420 246 436 262"/></g>
                <g class="trail-path"><path d="M288 142 C258 130 228 136 206 150 M362 166 C372 146 388 132 408 124 M546 224 C576 212 606 218 628 206 M522 272 C552 286 580 296 606 292 M206 150 C178 162 150 170 128 172"/></g>
                <g class="bridge" transform="translate(830 240) rotate(-18)"><rect x="-16" y="-5" width="32" height="10" rx="3"/><path d="M-11 -3v6M-4-3v6M3-3v6M10-3v6"/></g><g class="bridge" transform="translate(800 460) rotate(20)"><rect x="-16" y="-5" width="32" height="10" rx="3"/><path d="M-11 -3v6M-4-3v6M3-3v6M10-3v6"/></g>
                <g class="lookout" transform="translate(330 78)"><rect x="-5" y="-16" width="10" height="18" rx="2"/><polygon points="-10,-16 0,-24 10,-16"/><circle cx="0" cy="-8" r="3"/><text x="0" y="16">瞭望塔</text></g><g class="lookout" transform="translate(760 60)"><rect x="-5" y="-16" width="10" height="18" rx="2"/><polygon points="-10,-16 0,-24 10,-16"/><circle cx="0" cy="-8" r="3"/><text x="0" y="16">瞭望塔</text></g>
                <g class="closed-mark" transform="translate(300 470)"><circle r="13"/><path d="M-5 0H5"/><text x="0" y="26">游客止步</text></g><g class="closed-mark" transform="translate(842 498)"><circle r="13"/><path d="M-5 0H5"/><text x="0" y="26">保护区边界</text></g>
                <g class="road-label"><rect x="470" y="556" width="96" height="24" rx="12"/><text x="518" y="572">游客主游步道</text></g><g class="road-label"><rect x="370" y="300" width="88" height="24" rx="12"/><text x="414" y="316">护林巡护道</text></g>
                <g class="forest-label" transform="translate(150 480)"><path d="M0 8 l8-8 8 8-4 0 7 8H-3l7-8Z"/><text x="26" y="12">自然保护林区</text></g><g class="exit-mark" transform="translate(470 600)"><circle r="20"/><path d="M-7 0h14m-4-5 5 5-5 5"/><text x="0" y="38">游客中心集结点</text></g><g class="north-mark" transform="translate(950 45)"><path d="M0 28 L10 0 L20 28 L10 23 Z"/><text x="10" y="43">N</text></g>
              </svg>
              <div class="layer-legend"><span><i class="sensor"></i>传感器</span><span><i class="ranger"></i>护林员</span><span><i class="drone"></i>无人机</span></div>
            </div>
            <div class="zone-summary"><div><span>当前选区</span><b>{{ selectedZone.name }}</b></div><div><span>区域状态</span><el-tag :type="selectedZoneAlert==='evacuate'?'danger':selectedZoneAlert==='incident'?'warning':selectedZone.risk==='高'?'danger':'success'">{{ selectedZoneAlert==='evacuate'?'疏散警戒':selectedZoneAlert==='incident'?'警情关注':`${selectedZone.risk}风险` }}</el-tag></div><div><span>保护古树</span><b>{{ selectedZone.trees }} 株</b></div><div><span>数据来源</span><b>MySQL 业务库</b></div></div>
          </el-card>
          <div class="right-stack">
            <el-card shadow="never"><template #header><div class="card-head"><b>古树区实时数据</b><el-button text type="primary" @click="active='ancient'">查看全部</el-button></div></template><div v-if="sensors[0]" class="sensor-focus"><div class="focus-title"><span class="live-dot"></span><div><b>{{ sensors[0].name }}</b><small>{{ sensors[0].id }} · {{ sensors[0].source==='real'?'真机':'平台接入' }}</small></div><el-tag :type="nodeInfo(sensors[0]).type">{{ nodeInfo(sensors[0]).text }}</el-tag></div><div class="metric-grid"><div><span>烟雾</span><b :class="sensors[0].smoke>50?'danger-text':''">{{ valueText(sensors[0].smoke,'') }}</b><small>ppm</small></div><div><span>温度</span><b>{{ valueText(sensors[0].temperature,'') }}</b><small>℃</small></div><div><span>湿度</span><b>{{ valueText(sensors[0].humidity,'') }}</b><small>%RH</small></div><div><span>CO</span><b>{{ valueText(sensors[0].co,'') }}</b><small>ppm</small></div></div></div><el-empty v-else description="等待数据库返回监测数据" /></el-card>
            <el-card shadow="never"><template #header><div class="card-head"><b>今日巡护任务</b><el-button text type="primary" @click="active='drone'">任务中心</el-button></div></template><div class="task-mini" v-for="t in patrols.slice(0,2)" :key="t.id"><div class="task-status" :class="taskDisplayStatus(t)==='已完成'?'done':''"><el-icon><Position /></el-icon></div><div><b>{{ t.name }}</b><span>{{ t.planTime }} · {{ t.ranger }} · {{ t.drone }}</span></div><el-tag size="small" :type="taskStatusType(t)">{{ taskDisplayStatus(t) }}</el-tag></div></el-card>
          </div>
        </section>
      </template>

      <template v-else-if="active==='ancient'">
        <section class="stats compact"><article><div class="stat-icon green"><el-icon><Connection /></el-icon></div><div><span>在线监测节点</span><b>{{ sensors.filter(v=>v.online).length }}<small>/{{ sensors.length }}</small></b><em>状态来自设备数据表</em></div></article><article><div class="stat-icon red"><el-icon><Warning /></el-icon></div><div><span>异常节点</span><b>{{ sensors.filter(v=>['alarm','warning'].includes(v.status)).length }}<small>台</small></b><em>按最新一次上报状态统计</em></div></article><article><div class="stat-icon blue"><el-icon><Camera /></el-icon></div><div><span>固定摄像头</span><b>{{ sensors.filter(v=>v.camera).length }}<small>路</small></b><em>联动能力来自设备台账</em></div></article></section>
        <el-card shadow="never"><template #header><div class="card-head"><div><b>古树保护区实时监测</b><span>烟雾真机与温湿度、CO仿真数据统一接入</span></div><el-button @click="simulateTick">模拟刷新</el-button></div></template>
          <el-table :data="sensors" border stripe><el-table-column prop="id" label="节点编号" width="105"/><el-table-column prop="name" label="节点名称" min-width="155"/><el-table-column prop="zone" label="所属区域" min-width="160"/><el-table-column label="来源" width="90"><template #default="s"><el-tag size="small" :type="s.row.source==='real'?'success':'info'">{{ s.row.source==='real'?'真机':'仿真' }}</el-tag></template></el-table-column><el-table-column label="烟雾" width="95"><template #default="s"><b :class="s.row.smoke>50?'danger-text':''">{{ valueText(s.row.smoke,' ppm') }}</b></template></el-table-column><el-table-column label="温度" width="90"><template #default="s">{{ valueText(s.row.temperature,'℃') }}</template></el-table-column><el-table-column label="湿度" width="90"><template #default="s">{{ valueText(s.row.humidity,'%') }}</template></el-table-column><el-table-column label="CO" width="85"><template #default="s">{{ valueText(s.row.co,'') }}</template></el-table-column><el-table-column label="状态" width="100"><template #default="s"><el-tag :type="nodeInfo(s.row).type">{{ nodeInfo(s.row).text }}</el-tag></template></el-table-column><el-table-column label="操作" width="190" fixed="right"><template #default="s"><el-button size="small" @click="openNode(s.row)">趋势</el-button><el-button size="small" type="primary" :disabled="!s.row.camera" @click="reviewCamera({zone:s.row.zone,reason:'节点异常触发摄像复查',confidence:82})">摄像复查</el-button></template></el-table-column></el-table>
        </el-card>
      </template>

      <template v-else-if="active==='history'">
        <el-card shadow="never" class="history-card"><template #header><div class="card-head"><div><b>古树林区防火数据历史趋势</b><span>分析烟雾、温湿度变化与火险环境规律</span></div><div class="filters"><el-tag size="small" :type="trendSource==='real'?'success':'info'">{{ trendSourceText }}</el-tag><el-select v-model="historyNode" style="width:190px"><el-option v-for="n in sensors" :key="n.id" :label="n.name" :value="n.id"/></el-select><el-radio-group v-model="historyMetric"><el-radio-button value="smoke">烟雾</el-radio-button><el-radio-button value="temperature">温度</el-radio-button><el-radio-button value="humidity">湿度</el-radio-button></el-radio-group></div></div></template>
          <div class="trend-summary"><div><span>当前值</span><b>{{ trendCurrent }} {{ trendMeta.unit }}</b></div><div><span>窗口最高</span><b>{{ trendMax }} {{ trendMeta.unit }}</b></div><div><span>变化趋势</span><b :class="trendDirectionClass">{{ trendDirection }}</b></div><div><span>分析结论</span><b>{{ trendMeta.advice }}</b></div></div>
          <LiveLineChart v-loading="trendLoading" :data="trendData" :height="330" :unit="` ${trendMeta.unit}`" :threshold="trendMeta.threshold" :subtitle="trendSubtitle" show-x-axis />
        </el-card>
      </template>

      <template v-else-if="active==='incidents'">
        <el-card shadow="never"><template #header><div class="card-head"><div><b>火情事件中心</b><span>摄像头复查、无人机核查与护林员现场处置全过程</span></div><div class="incident-head-actions"><span>演示：</span><el-button size="small" :loading="simulateLoading" @click="simulateIncident('一级')">一级</el-button><el-button size="small" type="warning" plain :loading="simulateLoading" @click="simulateIncident('二级')">二级</el-button><el-button size="small" type="danger" plain :loading="simulateLoading" @click="simulateIncident('三级')">三级</el-button><el-radio-group v-model="incidentFilter"><el-radio-button value="all">全部</el-radio-button><el-radio-button value="active">处理中</el-radio-button><el-radio-button value="closed">已结案</el-radio-button></el-radio-group></div></div></template>
          <el-table :data="filteredIncidents" border stripe><el-table-column prop="id" label="事件编号" width="190"/><el-table-column prop="time" label="发现时间" width="170"/><el-table-column prop="zone" label="区域" min-width="160"/><el-table-column label="等级" width="90"><template #default="s"><el-tag :type="s.row.level==='三级'?'danger':s.row.level==='二级'?'warning':'info'">{{ s.row.level }}</el-tag></template></el-table-column><el-table-column prop="source" label="线索来源" width="130"/><el-table-column label="进度" width="120"><template #default="s"><el-tag :type="incidentInfo(s.row).type">{{ incidentInfo(s.row).text }}</el-tag></template></el-table-column><el-table-column label="操作" width="350" fixed="right"><template #default="s"><el-button size="small" @click="openIncident(s.row)">详情</el-button><el-button v-if="s.row.status==='pending'" size="small" type="primary" @click="reviewCamera(s.row)">摄像复查</el-button><el-button v-if="s.row.status==='verifying'&&!hasActiveMission(s.row.id)" size="small" type="warning" plain @click="goDronePatrol(s.row)">发布核查任务</el-button><el-button v-else-if="s.row.status==='verifying'" size="small" disabled>{{ s.row.ranger==='全体护林员' ? '全体护林员处置中' : s.row.ranger ? `已由${s.row.ranger}接取` : '等待护林员接取' }}</el-button><el-button v-if="s.row.status==='processing'" size="small" type="success" @click="closeIncident(s.row)">确认结果并结案</el-button><el-button v-if="s.row.source==='演示模拟'&&s.row.status!=='closed'" size="small" type="danger" link @click="endSimulation(s.row)">结束演示</el-button></template></el-table-column></el-table>
        </el-card>
      </template>

      <template v-else-if="active==='drone'">
        <DroneOperations :drones="drones" :sensors="sensors" :zones="mapZones" :patrols="patrols" :incidents="incidents" @detail="openPatrolDetail" />
      </template>

      <template v-else-if="active==='broadcast'">
        <section class="broadcast-layout"><el-card shadow="never"><template #header><div class="card-head"><div><b>广播与警示设备联动</b><span>向游客发布火情预警、区域封闭和疏散指令</span></div><el-tag type="success">8/8 设备在线</el-tag></div></template><el-form label-position="top"><el-form-item label="指令模板"><el-radio-group v-model="broadcast.type"><el-radio-button value="warning">火险提醒</el-radio-button><el-radio-button value="evacuate">紧急疏散</el-radio-button><el-radio-button value="close">区域封闭</el-radio-button><el-radio-button value="custom">自定义</el-radio-button></el-radio-group></el-form-item><el-form-item label="播报区域"><el-checkbox-group v-model="broadcast.areas"><el-checkbox v-for="z in zones" :key="z.id" :value="z.name">{{ z.name }}</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="游客提示内容"><el-input v-model="broadcast.message" type="textarea" :rows="5" maxlength="300" show-word-limit/></el-form-item><el-form-item label="推荐安全出口"><el-select v-model="broadcast.exit" style="width:100%"><el-option label="游客中心集结点" value="游客中心集结点"/><el-option label="北门安全出口" value="北门安全出口"/><el-option label="东门停车场" value="东门停车场"/></el-select></el-form-item><el-button type="danger" size="large" :disabled="!broadcast.areas.length" @click="publishBroadcast"><el-icon><Promotion /></el-icon> 下发广播与游客预警</el-button></el-form></el-card>
