idth="190"><template #default="s">{{ coordinatePair(s.row.longitude,s.row.latitude) }}</template></el-table-column><el-table-column prop="altitude" label="高度(m)" width="85"/><el-table-column prop="pm25" label="PM2.5" width="85"/><el-table-column prop="co" label="CO" width="75"/><el-table-column prop="surfaceTemperature" label="地表温度" width="95"/></el-table></el-tab-pane></el-tabs></div></el-drawer>
