const trendDirection=computed(()=>{if(trendData.value.length<2)return '样本不足';const first=Number(trendData.value[0].value),last=Number(trendData.value[trendData.value.length-1].value),tolerance=historyMetric.value==='smoke'?0.5:historyMetric.value==='temperature'?0.2:1;return last-first>tolerance?'上升':first-last>tolerance?'下降':'基本平稳'})
const trendDirectionClass=computed(()=>trendDirection.value==='上升'&&historyMetric.value!=='humidity'?'danger-text':'')
const trendSubtitle=computed(()=>trendSource.value==='real'?'最近 120 条真机采样 · 5 秒刷新':'仿真历史趋势')
const normalizeDrone=d=>({...d,thermal:Boolean(d.thermal),payloads:typeof d.payloads==='string'?d.payloads.split(',').filter(Boolean):(d.payloads||[]),telemetry:{pm25:d.pm25,temperature:d.temperature,humidity:d.humidity,co:d.co,surfaceTemperature:d.surfaceTemperature,windEstimate:d.windEstimate}})
async function loadForestData(){
  try{
    const res=await getForestBootstrap()
    if(res.code!==200)throw new Error(res.message||'森林业务数据加载失败')
    const data=res.data||{}
    Object.assign(parkInfo,data.parkInfo||{})
    Object.assign(weather,data.weather||{})
    Object.assign(riskAnalysis,data.riskAnalysis||{})
    zones.value=data.zones||[]
    sensors.value=(data.sensors||[]).map(v=>({...v,online:Boolean(v.online),camera:Boolean(v.camera)}))
    drones.value=(data.drones||[]).map(normalizeDrone)
    patrols.value=data.patrols||[]
    incidents.value=data.incidents||[]
    histories.smoke=data.smokeHistory||[];histories.temperature=data.temperatureHistory||[];histories.humidity=data.humidityHistory||[]
    rangers.value=data.rangers||[]
    const mapRow=data.map||null
    if(mapRow){mapCenter.value=[mapRow.centerLng!=null?mapRow.centerLng:PARK.center[0],mapRow.centerLat!=null?mapRow.centerLat:PARK.center[1]];mapZoom.value=mapRow.zoom!=null?mapRow.zoom:PARK.zoom}
    if(zones.value.length)selectedZone.value=zones.value[0]
    if(!sensors.value.some(v=>v.id===historyNode.value)&&sensors.value.length)historyNode.value=sensors.value[0].id
    if(!trendData.value.length)await loadSensorHistory(true)
    await loadBroadcastHistory(true)
  }catch(err){ElMessage.error(err.message||'无法连接森林业务数据库，请检查后端服务')}
}
async function loadBroadcastHistory(quiet=false){try{const res=await getForestBroadcastHistory(8);if(res.code!==200)throw new Error(res.msg||'广播记录加载失败');broadcastHistory.value=res.data||[]}catch(err){if(!quiet)ElMessage.error(err.message||'广播记录加载失败')}}
const broadcastRecordType=level=>level==='danger'||level==='evacuate'?'danger':level==='normal'?'success':'warning'
async function loadSensorHistory(quiet=false){
  if(!historyNode.value)return
  if(!quiet)trendLoading.value=true
  try{const res=await getForestSensorHistory(historyNode.value,historyMetric.value,120);if(res.code!==200)throw new Error(res.msg||'趋势加载失败');trendData.value=res.data?.points||[];trendSource.value=res.data?.source||'simulated';trendSourceText.value=res.data?.sourceText||'数据来源未知'}
  catch(err){if(!quiet)ElMessage.error(err.message||'历史趋势加载失败')}
  finally{trendLoading.value=false}
}
