  const next=sensors.value.map(n=>(n.online&&n.source!=='real')?{...n,smoke:Number((Number(n.smoke)+(Math.random()-.5)).toFixed(1)),temperature:Number((Number(n.temperature)+(Math.random()-.35)*.3).toFixed(1))}:n)
