function resetReview(){reviewImage.value='';reviewSource.value='';reviewTime.value='';reviewVerdict.value='';reviewVerdictText.value='';reviewBasis.value='';reviewDetections.value=[];reviewBoxes.value=[]}
function captureFrame(){return new Promise(resolve=>{if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia){resolve(null);return}navigator.mediaDevices.getUserMedia({video:{width:640,height:480},audio:false}).then(stream=>{const video=document.createElement('video');video.srcObject=stream;video.setAttribute('playsinline','');video.muted=true;let done=false;const shoot=()=>{if(done)return;done=true;clearTimeout(timer);const scale=Math.min(1,640/video.videoWidth);const canvas=document.createElement('canvas');canvas.width=Math.round(video.videoWidth*scale);canvas.height=Math.round(video.videoHeight*scale);canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);stream.getTracks().forEach(t=>t.stop());resolve(canvas.toDataURL('image/jpeg',0.6))};const timer=setTimeout(shoot,1500);video.oncanplay=()=>setTimeout(shoot,250);video.onloadeddata=()=>setTimeout(shoot,400);video.onerror=()=>{clearTimeout(timer);stream.getTracks().forEach(t=>t.stop());resolve(null)};video.play().catch(()=>{clearTimeout(timer);stream.getTracks().forEach(t=>t.stop());resolve(null)})}).catch(()=>resolve(null))})}
async function runAiReview(imageBase64,source){cameraLoading.value=true;reviewImage.value=imageBase64;reviewSource.value=source;try{await uploadReview({sensorId:cameraTarget.value.id||cameraTarget.value.camera||'CAM-01',zone:cameraTarget.value.zone||'',level:cameraTarget.value.level||'',smokeConcentration:resolveConcentration(cameraTarget.value),imageBase64});const latest=await getLatestReview();if(latest){reviewVerdict.value=latest.aiVerdict||'normal';reviewVerdictText.value=verdictMap[reviewVerdict.value]?.text||'无异常';reviewBasis.value=latest.aiBasis||'AI 服务已返回，但未给出判定依据';reviewDetections.value=Array.isArray(latest.aiDetections)?latest.aiDetections:[];reviewBoxes.value=Array.isArray(latest.aiBoxes)?latest.aiBoxes:[];reviewTime.value=latest.createTime||'';if(!reviewBoxes.value.length)ElMessage.info('YOLO 服务未连接，已按烟雾浓度融合判定')}else{ElMessage.warning('AI 复核完成，但未取到最新记录')}}catch(err){console.error(err);reviewBasis.value='后端或 YOLO 识别服务未启动，无法完成 AI 复核';ElMessage.error('AI 复核失败：后端 / YOLO 服务未启动')}finally{cameraLoading.value=false}}
