async function confirmCamera(){
  if(confirmLoading.value)return
  confirmLoading.value=true
  try{
    const target=incidents.value.find(i=>i.id===cameraTarget.value.id&&i.status!=='closed')||incidents.value.find(i=>i.zone===cameraTarget.value.zone&&i.status==='pending')
    if(target){await updateForestIncident(target.id,{status:'verifying',result:target.result||'',ranger:userName.value});target.status='verifying';target.ranger=userName.value}
    else{
      const sensor=sensors.value.find(s=>s.zone===cameraTarget.value.zone)
      const res=await createForestIncident({zone:cameraTarget.value.zone||sensor?.zone||'待确认区域',level:cameraTarget.value.level||'二级',source:'固定摄像头复查',status:'verifying',smoke:resolveConcentration(cameraTarget.value),temperature:cameraTarget.value.temperature??sensor?.temperature,confidence:Math.round((reviewTopConf.value||Number(cameraTarget.value.confidence)/100||0.8)*100),reason:reviewVerdictText.value?`摄像头复查判定：${reviewVerdictText.value}`:'护林员已通过固定摄像头确认为疑似火情',result:'',ranger:userName.value})
      if(res.code!==200)throw new Error(res.msg||'警情创建失败')
      incidents.value.unshift(res.data)
    }
    cameraDrawer.value=false;active.value='incidents';await loadForestData();ElMessage.success(parkEvacuating.value?'三级警情已启动全园清场、广播和全体护林员共同处置':'已确认为疑似火情，请调度无人机热成像核查')
  }catch(err){ElMessage.error(err.message||'警情进度保存失败')}finally{confirmLoading.value=false}
}
