  if(simulateLoading.value)return
  if(level==='三级'){try{await ElMessageBox.confirm('三级演示会立即将全园切换为疏散状态、发布清场广播并通知全体护林员，是否继续？','启动三级警情演示',{type:'warning',confirmButtonText:'启动演示',cancelButtonText:'取消'})}catch{return}}
  simulateLoading.value=true
  try{const res=await simulateForestIncident({level,zone:selectedZone.value?.name||''});if(res.code!==200)throw new Error(res.msg||'模拟警情生成失败');await loadForestData();active.value='incidents';ElMessage.success(`${level}演示警情已生成${level==='三级'?'，全园应急联动已启动':''}`)}catch(err){ElMessage.error(err.message||'模拟警情生成失败')}finally{simulateLoading.value=false}
}
