function onDrawComplete(path){if(!path||path.length<3)return ElMessage.warning('请至少绘制 3 个点构成边界');const ring=path.map(p=>[Number(p[0]),Number(p[1])]);const first=ring[0],last=ring[ring.length-1];if(first[0]!==last[0]||first[1]!==last[1])ring.push([...first]);const lng=ring.reduce((s,p)=>s+p[0],0)/ring.length,lat=ring.reduce((s,p)=>s+p[1],0)/ring.length;zoneForm.value.geojson=JSON.stringify({type:'Polygon',coordinates:[ring]});zoneForm.value.latitude=round6(lat);zoneForm.value.longitude=round6(lng);zoneManagerOpen.value=true;ElMessage.success('边界已绘制，确认名称等信息后点击「保存」')}
let viewSaveTimer
function onViewChange(v){if(viewSaveTimer)clearTimeout(viewSaveTimer);viewSaveTimer=setTimeout(async()=>{try{await saveMapView({centerLng:round6(v.lng),centerLat:round6(v.lat),zoom:v.zoom})}catch{/* 视图持久化失败静默忽略 */}},1200)}
async function saveZone(){if(!zoneForm.value.name)return ElMessage.warning('请填写区域名称');const payload={name:zoneForm.value.name,type:zoneForm.value.type,risk:zoneForm.value.risk,trees:zoneForm.value.trees,geojson:zoneForm.value.geojson,latitude:zoneForm.value.latitude,longitude:zoneForm.value.longitude};try{if(zoneForm.value.id!=null)await updateForestZone(zoneForm.value.id,payload);else await createForestZone(payload);zoneManagerOpen.value=false;await loadForestData();ElMessage.success('分区已保存')}catch{ElMessage.error('分区保存失败')}}
async function deleteZone(zone){
  try{
    await ElMessageBox.confirm(`确定删除“${zone.name}”吗？分区边界会被移除，所属设备将转为“未分区”，历史警情仍会保留。`,'删除分区',{type:'warning',confirmButtonText:'确认删除',cancelButtonText:'取消'})
    const res=await deleteForestZone(zone.id)
    if(res.code!==200)throw new Error(res.msg||'分区删除失败')
    if(String(selectedZone.value.id)===String(zone.id))selectedZone.value={name:'请选择分区',risk:'低',trees:0}
    if(String(zoneForm.value.id)===String(zone.id))newZone()
    await loadForestData()
    ElMessage.success('分区已删除')
  }catch(err){if(err!=='cancel'&&err!=='close')ElMessage.error(err.message||'分区删除失败')}
}
function logout(){ElMessageBox.confirm('确定退出护林员工作台吗？','提示',{type:'warning'}).then(()=>{localStorage.removeItem('token');localStorage.removeItem('currentUser');router.push('/login')}).catch(()=>{})}
</script>

